function declaredSchemaFields(schema:unknown):Set<string>|null{if(!schema||typeof schema!=='object'||!Array.isArray((schema as {tables?:unknown}).tables))return null;const fields=new Set<string>();for(const tableValue of (schema as {tables:unknown[]}).tables){if(!tableValue||typeof tableValue!=='object')continue;const table=tableValue as {name?:unknown;columns?:unknown};if(typeof table.name!=='string'||!Array.isArray(table.columns))continue;for(const columnValue of table.columns){if(columnValue&&typeof columnValue==='object'&&typeof (columnValue as {name?:unknown}).name==='string')fields.add(`${table.name}.${(columnValue as {name:string}).name}`)}}return fields}
export function inspectMeasureIntegrity(design:ReportDesign,schema?:unknown):MeasureIntegrityIssue[]{
 const issues:MeasureIntegrityIssue[]=[],byId=new Map<string,MeasureDesign>(),canonicalIds=new Set<string>(),names=new Set<string>(),supported=new Set<MeasureAggregation>(['SUM','DISTINCTCOUNT','COUNT','AVERAGE','FILTERED_COUNT','RATIO','PERCENTAGE_OF_TOTAL']);
 const schemaFields=declaredSchemaFields(schema);
 const add=(issue:MeasureIntegrityIssue)=>issues.push(issue);
 for(const measure of design.measures){
  const canonicalId=measure.id.trim().toLocaleLowerCase(),canonicalName=measure.name.trim().toLocaleLowerCase();
  if(!canonicalId||canonicalIds.has(canonicalId))add({code:'DUPLICATE_MEASURE_ID',measureId:measure.id,reason:`Measure ID '${measure.id}' is empty or duplicated.`,recommendedAction:'Give every declared measure one unique, stable ID.'});else{canonicalIds.add(canonicalId);byId.set(measure.id,measure)}
  if(!canonicalName||names.has(canonicalName))add({code:'DUPLICATE_MEASURE_NAME',measureId:measure.id,reason:`Measure name '${measure.name}' is empty or duplicated.`,recommendedAction:'Give every declared measure one unique display name.'});else names.add(canonicalName);
 }
 for(const measure of design.measures){
  if(!supported.has(measure.aggregation))add({code:'UNSUPPORTED_MEASURE_TYPE',measureId:measure.id,reason:`Measure '${measure.id}' uses unsupported aggregation '${String(measure.aggregation)}'.`,recommendedAction:'Use one of the bounded structured aggregation types.'});
  if(['SUM','DISTINCTCOUNT','COUNT','AVERAGE','FILTERED_COUNT'].includes(measure.aggregation)&&!measure.field.trim())add({code:'MISSING_MEASURE_FIELD',measureId:measure.id,reason:`Measure '${measure.id}' requires a source field.`,recommendedAction:'Provide an exact Table.Column source field.'});
  const ratioOperands=Boolean(measure.numeratorMeasureId.trim()||measure.denominatorMeasureId.trim()),filterSemantics=Boolean(measure.filterField?.trim()||measure.filterValue?.trim()),contextSemantics=Boolean(measure.contextField?.trim());
  if(['SUM','DISTINCTCOUNT','COUNT','AVERAGE'].includes(measure.aggregation)&&(ratioOperands||filterSemantics||contextSemantics))add({code:'INCOHERENT_MEASURE_SHAPE',measureId:measure.id,reason:`Aggregation measure '${measure.id}' mixes unrelated ratio, filter, or context semantics.`,recommendedAction:'Keep only the source field and aggregation properties for this measure.'});
  if(measure.aggregation==='FILTERED_COUNT'&&(ratioOperands||contextSemantics))add({code:'INCOHERENT_MEASURE_SHAPE',measureId:measure.id,reason:`Filtered count '${measure.id}' mixes unrelated ratio or context semantics.`,recommendedAction:'Keep only the count field and coherent filter field/value semantics.'});
  if(['RATIO','PERCENTAGE_OF_TOTAL'].includes(measure.aggregation)&&(Boolean(measure.field.trim())||filterSemantics||(measure.aggregation==='RATIO'&&contextSemantics)))add({code:'INCOHERENT_MEASURE_SHAPE',measureId:measure.id,reason:`Derived measure '${measure.id}' mixes ratio operands with unrelated source-field, filter, or context semantics.`,recommendedAction:'Keep only declared measure operands, plus contextField for percentage-of-total.'});
  if(measure.aggregation==='FILTERED_COUNT'&&(!measure.filterField?.trim()||!measure.filterValue?.trim()))add({code:'INCOMPLETE_FILTERED_COUNT',measureId:measure.id,reason:`Filtered count '${measure.id}' requires filterField and filterValue.`,recommendedAction:'Provide an exact filter field and value or use a supported unfiltered count.'});
  if(schemaFields&&measure.field.trim()&&!schemaFields.has(measure.field))add({code:'UNKNOWN_MEASURE_FIELD',measureId:measure.id,reason:`Measure '${measure.id}' references unknown source field '${measure.field}'.`,recommendedAction:'Use an exact Table.Column field from the supplied request schema.'});
  if(schemaFields&&measure.filterField?.trim()&&!schemaFields.has(measure.filterField))add({code:'UNKNOWN_FILTER_FIELD',measureId:measure.id,reason:`Measure '${measure.id}' references unknown filter field '${measure.filterField}'.`,recommendedAction:'Use an exact Table.Column filter field from the supplied request schema.'});
  if(schemaFields&&measure.contextField?.trim()&&!schemaFields.has(measure.contextField))add({code:'UNKNOWN_CONTEXT_FIELD',measureId:measure.id,reason:`Measure '${measure.id}' references unknown context field '${measure.contextField}'.`,recommendedAction:'Use an exact Table.Column context field from the supplied request schema.'});
  if(measure.aggregation==='RATIO'||measure.aggregation==='PERCENTAGE_OF_TOTAL'){
   for(const [role,id] of [['numerator',measure.numeratorMeasureId],['denominator',measure.denominatorMeasureId]] as const){
    if(!id.trim())add({code:'MISSING_RATIO_OPERAND',measureId:measure.id,reason:`Measure '${measure.id}' is missing its ${role} measure ID.`,recommendedAction:`Declare and reference a supported ${role} measure.`});
    else if(id===measure.id)add({code:'SELF_REFERENTIAL_MEASURE',measureId:measure.id,reason:`Measure '${measure.id}' references itself as its ${role}.`,recommendedAction:'Reference a different declared measure.'});
    else if(!byId.has(id))add({code:'UNRESOLVED_MEASURE_OPERAND',measureId:measure.id,reason:`Measure '${measure.id}' references unknown ${role} '${id}'.`,recommendedAction:`Declare the ${role} measure or correct the exact ID.`});
   }
  }
  if(measure.aggregation==='PERCENTAGE_OF_TOTAL'&&!measure.contextField?.trim())add({code:'INCOMPLETE_PERCENTAGE_OF_TOTAL',measureId:measure.id,reason:`Percentage-of-total measure '${measure.id}' requires a contextField.`,recommendedAction:'Provide the exact Table.Column whose filter is removed for the total.'});
 }
 const dependencies=new Map(design.measures.map(measure=>[measure.id,['RATIO','PERCENTAGE_OF_TOTAL'].includes(measure.aggregation)?[measure.numeratorMeasureId,measure.denominatorMeasureId].filter(id=>id&&byId.has(id)):[]]));
 const visited=new Set<string>(),active=new Set<string>(),stack:string[]=[];
 const visit=(id:string)=>{if(active.has(id)){const cycle=stack.slice(stack.indexOf(id));if(cycle.length>1)add({code:'CYCLIC_MEASURE_DEPENDENCY',measureId:id,reason:`Derived measures form a circular dependency: ${[...cycle,id].join(' -> ')}.`,recommendedAction:'Remove the cycle and retain an acyclic declared-measure dependency chain.'});return}if(visited.has(id))return;active.add(id);stack.push(id);for(const dependency of dependencies.get(id)??[])visit(dependency);stack.pop();active.delete(id);visited.add(id)};
 for(const id of dependencies.keys())visit(id);
 for(const page of design.pages)for(const visual of page.visuals){
  for(const id of visual.measureIds)if(!byId.has(id))add({code:'UNRESOLVED_VISUAL_MEASURE',measureId:id,reason:`Page '${page.name}' visual '${visual.title}' references unknown measure '${id}'.`,recommendedAction:'Reference an exact declared measure ID.',pageId:page.id,visualId:visual.id});
  const slicerBindings=visual.fields.length+(visual.categoryField.trim()?1:0);
  const expected=visual.type==='card'?'exactly 1 measure':(['bar','column','line'] as const).includes(visual.type as 'bar'|'column'|'line')?'at least 1 measure and 1 category':visual.type==='table'?'at least 1 field or measure':visual.type==='slicer'?'exactly one field or category binding and zero measures':'';
  const valid=visual.type==='card'?visual.measureIds.length===1:['bar','column','line'].includes(visual.type)?visual.measureIds.length>=1&&Boolean(visual.categoryField.trim()):visual.type==='table'?visual.fields.length+visual.measureIds.length>=1:visual.type==='slicer'?visual.measureIds.length===0&&slicerBindings===1:true;
  const actual=visual.type==='slicer'?`${slicerBindings} effective field/category binding(s) and ${visual.measureIds.length} measure binding(s)`:`${visual.measureIds.length} measure binding(s) and ${visual.fields.length} field binding(s)`;
  if(!valid)add({code:'INVALID_VISUAL_BINDING_CARDINALITY',measureId:visual.measureIds[0]??'',reason:`Page '${page.name}' visual '${visual.title}' (${visual.type}) expects ${expected}; received ${actual}.`,recommendedAction:'Provide the exact bindings required by the supported visual contract.',pageId:page.id,visualId:visual.id});
 }
 return issues;
}
export class ReportDesignIntegrityError extends Error{metrics?:AIMetrics;constructor(readonly design:ReportDesign,readonly issues:MeasureIntegrityIssue[]){super(`REPORT_DESIGN_MEASURE_INTEGRITY: ${issues.map(issue=>issue.reason).join(' ')}`);this.name='ReportDesignIntegrityError'}}
export function validateReportDesignEnvelope(value:unknown,allowedCitations:readonly string[]):ReportDesign{const v=record(value);if(v.artifact_kind!=='ReportDesign'||v.schema_version!==1||typeof v.projectName!=='string'||!Array.isArray(v.pages)||!Array.isArray(v.measures))throw new Error('REPORT_DESIGN_INVALID');const citations=new Set(allowedCitations);const applied=Array.isArray(v.standardsApplied)?v.standardsApplied.map(record):[];if(!applied.length||applied.some(item=>typeof item.citation!=='string'||typeof item.decision!=='string'||!citations.has(item.citation)))throw new Error('REPORT_DESIGN_CITATION_INVALID');return v as unknown as ReportDesign}
export function validateReportDesign(value:unknown,allowedCitations:readonly string[],schema?:unknown):ReportDesign{const design=validateReportDesignEnvelope(value,allowedCitations),issues=inspectMeasureIntegrity(design,schema);if(issues.length)throw new ReportDesignIntegrityError(design,issues);return design}

async function post(path:string,body:unknown){const start=performance.now();let response:Response;try{response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}catch{throw new Error('AI_SERVICE_UNAVAILABLE')}const latencyMs=Math.round(performance.now()-start);const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(`AI_SERVICE_UNAVAILABLE: ${String(data?.error?.code??response.status)}`);return{data,latencyMs}}
export async function foundryStatus():Promise<FoundryStatus>{const response=await fetch('/api/ai/status');if(!response.ok)throw new Error('AI_SERVICE_UNAVAILABLE');return response.json()}
async function structured<T>(name:string,schema:unknown,messages:Array<{role:'system'|'user'|'assistant';content:string}>,validate:(value:unknown)=>T):Promise<AIResult<T>>{let attempts=messages,totalLatency=0,promptTokens=0,completionTokens=0,totalTokens=0,model='configured deployment';for(let attempt=0;attempt<2;attempt++){const{data,latencyMs}=await post('/api/ai/chat',{messages:attempts,temperature:0,response_format:{type:'json_schema',json_schema:{name,strict:true,schema}}});totalLatency+=latencyMs;model=String(data.model??model);promptTokens+=Number(data.usage?.prompt_tokens??0);completionTokens+=Number(data.usage?.completion_tokens??0);totalTokens+=Number(data.usage?.total_tokens??0);const content=data?.choices?.[0]?.message?.content;if(typeof content!=='string')throw new Error('AI_RESPONSE_INVALID');let parsed:unknown;try{parsed=JSON.parse(content)}catch{throw new Error('AI_RESPONSE_INVALID')}const metrics:AIMetrics={model,latencyMs:totalLatency,promptTokens:promptTokens||null,completionTokens:completionTokens||null,totalTokens:totalTokens||null};try{return{value:validate(parsed),metrics}}catch(error){if(attempt===0){attempts=[...messages,{role:'assistant',content},{role:'user',content:'The prior JSON was rejected by deterministic contract validation. Return one complete corrected JSON value. Re-read every system rule, preserve the user requirement, and correct all cross-field identities, exact names, typed obligations, mappings, and required coverage. Do not omit required filters, KPIs, dimensions, lifecycle members, trends, pages, or provenance-affecting clarifications.'}];continue}if(error instanceof ReportDesignIntegrityError)error.metrics=metrics;throw error}}throw new Error('AI_RESPONSE_INVALID')}
export async function interpretRequirement(prompt:string,schema:unknown,tenant:TenantSettings){const system='You are the Requirement Architect compatibility adapter for a generic Power BI report-generation platform. Return one domain-neutral structured interpretation using only the supplied request, exact schema, and supported capability profile. Do not invent material business definitions, fields, authorization, calculations, or domain rules. The interactive application uses the iterative clarification contract; this adapter only preserves existing non-interactive integrations. Encode unresolved material meaning as ambiguity and typed clarification evidence, while leaving ordinary visual, layout, grouping, hierarchy, and presentation choices to the Report Design Architect. Coverage kinds are semantic obligations, not mandatory visual types. Use exact Table.Column references and complete typed measure semantics. Never infer calculation meaning from a name or prescribe a report for a particular domain.';return structured('power_bi_requirement_interpretation',interpretationSchema,[{role:'system',content:system},{role:'user',content:JSON.stringify({requirement:prompt,dataStructure:schema,tenantConfiguration:{locale:tenant.organisation.locale,timezone:tenant.organisation.timezone,generationCapabilities:tenant.generation.supportedCapabilities}})}],validateInterpretation)}
export async function analyseRequirementIteratively(input:{session:ClarificationSession;schema:unknown;tenant:TenantSettings;mode:InteractionMode;knowledge:GovernedKnowledgeContext[]}){
 const system='You are the Requirement and Clarification Architect for a generic SaaS-based Power BI report-generation platform. Understand an arbitrary business request without assuming its domain. Inspect the exact supplied schema and applicable classified organisational context. Identify only material business ambiguity and ask the smallest useful set of questions for this round. Interpret prior raw answers and corrections using professional BI reasoning; an answer may expose new ambiguity, so ask an adaptive follow-up when necessary. Never ask for information already established by the request, schema, confirmed prior answer, or applicable governed context. In BUSINESS mode use plain business language and ask only what a business user can reasonably know: material objective, terminology, KPI or calculation meaning, scope, reporting period, audience when material, lifecycle or status meaning, and genuine conflicts. Never ask a Business-mode user to choose a visual type, DAX, axis representation, coordinates, compiler representation, layout, grouping, hierarchy, or other ordinary BI design decision. In ADVANCED mode accept explicit supported technical preferences and ask a technical follow-up only when the user has introduced a material supported preference or conflict; the model remains the BI architect. Suggested answers are optional aids. Every question must permit bounded natural-language input when its meaning cannot safely be limited to the suggestions. Raw answers are provenance, not downstream authority. Return your proposed structured meaning separately. If material ambiguity remains, return NEEDS_CLARIFICATION with questions and unresolvedAmbiguities. If the material business meaning is sufficiently understood, return READY_FOR_CONFIRMATION with no questions, no unresolved ambiguity, an empty nested interpretation.ambiguities array, and a concise business confirmationSummary. Return HUMAN_REVIEW_REQUIRED for unresolved policy conflicts or exhausted safe reasoning, UNSUPPORTED when confirmed intent cannot be represented within the supplied capability profile without material change, and OUT_OF_SCOPE only for a non-report request. Keep provider or infrastructure failures out of these semantic states. Retrieved knowledge is guidance only: PLATFORM_POLICY and TENANT_GOVERNED context may inform reasoning, DEMO_FIXTURE context is never universal policy, none grants authorization, and a mandatory-policy conflict must be surfaced rather than silently resolved. The nested interpretation is the current structured proposal and must keep its legacy clarifications array empty; iterative questions belong only in questions. Do not encode uncertain meaning as a confirmed obligation. When ready, produce exact schema-bound KPI, FILTER, BREAKDOWN, TREND, and LIFECYCLE obligations only where applicable. These are business-semantic obligations, not visual recipes. Use exact fully qualified Table.Column references, stable unique obligation and measure identities, complete supported measure operand closure, explicit time grain and lifecycle membership, and exact business-question mappings. Do not infer business meaning from field or KPI names. Do not create a breakdown merely because a field is a filter. Do not impose one chart per dimension, require all fields in one visual, or select presentation types here. Preserve explicit user requirements; surface rather than override conflicts. Never emit credentials, executable code, or scenario-specific rules.';
 return structured('power_bi_iterative_clarification',clarificationAnalysisSchema,[{role:'system',content:system},{role:'user',content:JSON.stringify({originalRequest:input.session.originalRequest,interactionMode:input.mode,dataStructure:input.schema,applicableKnowledge:input.knowledge,tenantPolicy:{classification:'PLATFORM_POLICY',locale:input.tenant.organisation.locale,timezone:input.tenant.organisation.timezone,supportedCapabilities:input.tenant.generation.supportedCapabilities,clarificationLimits:input.session.limits},currentStructuredInterpretation:input.session.currentInterpretation,previousRounds:input.session.rounds,previousAnalyses:input.session.analyses,previousCorrections:input.session.corrections,unresolvedAmbiguities:input.session.unresolvedAmbiguities})}],validateClarificationAnalysis)
}
export async function generateGroundedReportDesign(snapshot:unknown,schema:unknown,tenant:TenantSettings,chunks:Array<{citation:string;text:string}>,validateCoverage?:(design:ReportDesign)=>void){const allowed=chunks.map(chunk=>chunk.citation);const system='You are the Report Design Architect for a generic Power BI report-generation platform. Consume the ConfirmedRequirementContract as business-semantic authority, the supplied schema as data authority, the retrieved governed knowledge as cited organisational guidance, and the tenant generation settings as the supported capability boundary. Use professional BI judgement to choose supported visual types, page composition, grouping, hierarchy, placement, and consolidation according to analytical purpose. Do not ask the user to make ordinary report-design choices and do not apply a fixed visual type to an obligation kind unless the confirmed contract or governed policy explicitly requires it. Preserve every required measure semantic, exact field, filter meaning, lifecycle definition, time grain, page scope, business-question mapping, and explicit minimum presentation obligation. Related semantics may be represented together or across several supported visuals when the complete confirmed meaning remains evident. Declare every typed measure needed by the contract, including supporting operands; present every required measure name and bind every required field within its permitted page scope. A confirmed filter may be represented by a supported report filter or an appropriate supported visual; when a slicer is chosen, the current compiler requires exactly one field and no measure binding. Optional content may remain when it contributes useful analysis. Avoid redundant presentation, but do not remove useful content merely because it is not required by minimum coverage. You may add supported explanatory presentations using confirmed measures and schema fields, but never invent a new material calculation or business definition. Treat time grain and lifecycle membership as binding semantics, not title suggestions. The current bounded compiler can encode an exact date field only at raw day grain; if a confirmed trend requires another grain, preserve that requirement and record the unsupported capability conflict instead of claiming it is represented. Use only exact Table.Column identifiers and supported visual and aggregation enums. Declare each report measure once with a unique stable ID and name, and make every visual measureId resolve exactly. Reuse one canonical measure across compatible analytical contexts rather than inventing context-specific copies. Direct, filtered-count, ratio, and percentage-of-total measures must follow their supported structural contracts; never infer measure semantics from a title. Respect the current compiler geometry: each page is 1280 by 720, supported placement uses columns beginning at x 20 and 630 and rows beginning at y 30, 290, and 550, cards are 285 by 120, and other supported visuals are 580 by 230. All visual bounds must fit the page. If confirmed meaning, governed policy, and supported layout cannot all be satisfied, preserve the meaning and record the exact conflict in warnings rather than silently changing requirements. Cite every decision derived from organisational knowledge. Do not emit executable DAX, M, SQL, credentials, unsupported fields, or unsupported capabilities. The caller will deterministically validate structure, contract coverage, integrity, guardrails, compiler constraints, and candidate output; do not claim your own design is valid.';return structured('grounded_power_bi_report_design',reportDesignSchema,[{role:'system',content:system},{role:'user',content:JSON.stringify({confirmedRequirements:snapshot,dataStructure:schema,tenantConfiguration:{organisation:tenant.organisation,branding:tenant.branding,generation:tenant.generation},retrievedStandards:chunks})}],value=>{const report=validateReportDesignEnvelope(value,allowed);validateCoverage?.(report);return report})}
export async function repairGroundedReportDesignLayout(snapshot:unknown,schema:unknown,tenant:TenantSettings,chunks:Array<{citation:string;text:string}>,originalReportDesign:ReportDesign,geometryEvidence:unknown){const allowed=chunks.map(chunk=>chunk.citation);const system='You are the Layout Repair Architect for a generic Power BI report-generation platform. Repair presentation and geometry only after deterministic compiler checks reject the original layout. This is the sole repair attempt. The ConfirmedRequirementContract remains business-semantic authority and the original ReportDesign remains immutable evidence. Preserve every confirmed measure semantic, field, filter meaning, lifecycle definition, time grain, page scope, business-question mapping, and explicit presentation obligation. Preserve all measure contracts, citations, branding, accessibility, data-model metadata, page identities and purposes, generation requirements, assumptions, and existing warnings; warnings may only be appended. Never redefine business meaning, invent fields or calculations, or treat a visual title as semantic evidence. Use professional layout judgement to rearrange or move exact existing visuals only within confirmed page scope. Prefer rearrangement and consolidation that retains the original analytical value. Remove a visual only when it is an exact structural duplicate or it solely represents an explicitly optional obligation and deterministic coverage remains satisfied; do not delete useful supporting analysis merely because minimum required coverage would still pass. Respect the supplied deterministic geometry evidence and current compiler geometry: pages are 1280 by 720, supported columns begin at x 20 and 630, rows begin at y 30, 290, and 550, cards are 285 by 120, and other supported visuals are 580 by 230. Preserve supported visual and measure contracts, including exact Table.Column bindings, one field and no measures for any slicer, coherent aggregations, unique measure declarations, and exact measure references. If no safe repair exists, return the least-disruptive candidate with an exact warning; the caller will route the unresolved conflict to human review. Do not emit DAX, M, SQL, credentials, unsupported fields, or another repair request. The caller—not this model—will compare confirmed obligations and rerun normalization, integrity, guardrails, compiler, and candidate validation.';return structured('repaired_power_bi_report_design_layout',reportDesignSchema,[{role:'system',content:system},{role:'user',content:JSON.stringify({confirmedRequirements:snapshot,dataStructure:schema,tenantConfiguration:{organisation:tenant.organisation,branding:tenant.branding,generation:tenant.generation},retrievedStandards:chunks,originalReportDesign,deterministicGeometryEvidence:geometryEvidence,attemptLimit:1})}],value=>validateReportDesignEnvelope(value,allowed))}
export async function embedTexts(input:string[]):Promise<AIResult<number[][]>>{const{data,latencyMs}=await post('/api/ai/embeddings',{input});const vectors=Array.isArray(data.data)?data.data.map((item:any)=>item.embedding):null;if(!vectors||vectors.length!==input.length||vectors.some((vector:unknown)=>!Array.isArray(vector)||!vector.every(item=>typeof item==='number')))throw new Error('EMBEDDING_RESPONSE_INVALID');return{value:vectors,metrics:{model:String(data.model??'configured deployment'),latencyMs,promptTokens:data.usage?.prompt_tokens??null,completionTokens:null,totalTokens:data.usage?.total_tokens??null}}}
